          + (f" · rel-ĐÃ-PHỦ-ĐỊNH: {rep['relation_negated_count']} (S-1 cross-check, bỏ khỏi hàng đợi)"
             if rep.get("relation_negated_count") else "")
          + (f" · REVIEW-khác: {len(rep['review_other'])}" if rep["review_other"] else "")
